  python3 tools/logprob_diff.py save  NAME          # store the current arm's logprobs
  python3 tools/logprob_diff.py check NAME          # current arm vs stored NAME
  python3 tools/logprob_diff.py compare A B         # stored A vs stored B (symmetric)

Teacher forcing (``--logprob-start-len`` + a forced continuation) makes the comparison
independent of sampling drift: two"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=2))
        print(f"  saved {path}")
    elif cmd == "check":
        ref = json.loads((D / f"{sys.argv[2]}.json").read_text())
        cur = collect(ref)
        report = stats(ref, cur)
        print_report(f"{sys.argv[2]} vs current", report)
    elif cmd == "compare":
        a = json.loads((D / f"{sys.argv[2]}.json").read_text())
        b = json.loads((D / f"{sys.argv[3]}.json").read_text())
        report = stats(a, b)
        print_report(f"{sys.argv[3]} vs {sys.argv[2]}", report)
    else:
        print(__doc__)
        sys.exit(1)


if __name__ == "__main__":
    main()


